 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    row_walls = [r for r in range(h) if all(v == 8 for v in grid[r])]
    col_walls = [c for c in range(w) if all(grid[r][c] == 8 for r in range(h))]
    rb, cb = [-1] + row_walls + [h], [-1] + col_walls + [w]
    nr, nc = len(rb) - 1, len(cb) - 1
    out = [row[:] for row in grid]
    marks = {}
    for i in range(nr):
        for j in range(nc):
            colors = {
                grid[r][c]
                for r in range(rb[i] + 1, rb[i + 1])
                for c in range(cb[j] + 1, cb[j + 1])
                if grid[r][c] not in (0, 8)
            }
            if colors:
                marks[i, j] = colors

    painted = {}
    for color in {color for colors in marks.values() for color in colors}:
        cells = [(i, j) for (i, j), colors in marks.items() if color in colors]
        for i in range(nr):
            js = [j for r, j in cells if r == i]
            if len(js) >= 2:
                for j in range(min(js), max(js) + 1):
                    painted.setdefault((i, j), set()).add(color)
        for j in range(nc):
            rows = [i for i, c in cells if c == j]
            if len(rows) >= 2:
                for i in range(min(rows), max(rows) + 1):
                    painted.setdefault((i, j), set()).add(color)

    for (i, j), colors in painted.items():
        value = 6 if len(colors) > 1 else next(iter(colors))
        for r in range(rb[i] + 1, rb[i + 1]):
            for c in range(cb[j] + 1, cb[j + 1]):
                out[r][c] = value
    return out
